"""Build the certificate archive using existing, unmodified originals."""
from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parent
items=json.loads((root/'content.json').read_text())
site=root.parent.parent/'dist'
cards=[]
for i,item in enumerate(items):
 for key in ['preview','original']:
  assert (site/item[key].lstrip('/')).is_file(), item[key]
 cards.append('<article><a class="preview" href="{original}" target="_blank" rel="noopener noreferrer" aria-label="查看原件：{title}，{award}（新标签页）"><img src="{preview}" alt="{title} {award}证书" loading="lazy" width="1000" height="720"><span>查看原件 ↗</span></a><div class="meta"><span>{year}</span><span>{number}</span></div><h2>{title}</h2><p>{award}</p></article>'.format(number=str(i+1).zfill(2),**{k:escape(str(v),quote=True) for k,v in item.items()}))
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>证书档案 · Le-soleile</title><link rel="icon" href="/avatar.jpg"><style>
:root{color-scheme:dark;--text:#ece8dd;--muted:#b6b0a4;--line:#fff5dc18;--accent:#d4ad63}*{box-sizing:border-box}body{margin:0;background:#10110f;color:var(--text);font-family:"PingFang SC","Microsoft YaHei",sans-serif;line-height:1.75}a{color:inherit;text-decoration:none}a:focus-visible{outline:2px solid var(--accent);outline-offset:5px}header,main,footer{width:min(1200px,calc(100% - 80px));margin:auto}header{padding:28px 0;display:flex;justify-content:space-between;border-bottom:1px solid var(--line);font-size:14px}header a:hover{color:var(--accent)}.intro{padding:80px 0 56px;display:flex;justify-content:space-between;align-items:end;gap:32px}.eyebrow{font:12px monospace;letter-spacing:.14em;color:var(--accent)}h1{font-family:"Noto Serif SC","Songti SC",SimSun,serif;font-size:clamp(38px,5vw,64px);font-weight:600;line-height:1.2;margin:20px 0} .intro p{color:var(--muted);font-size:16px;max-width:30em;margin:0}.total{font:300 72px/1 Georgia,serif;color:var(--accent)}.total small{display:block;font:12px/2 monospace;color:var(--muted);letter-spacing:.12em;margin-top:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:56px 32px}.preview{display:block;position:relative;background:#1b1d19;border:1px solid var(--line);padding:24px;border-radius:12px;overflow:hidden}.preview img{display:block;width:100%;height:auto;aspect-ratio:1.4;object-fit:contain;transition:transform .25s}.preview:hover img{transform:scale(1.025)}.preview span{display:block;text-align:right;font-size:13px;color:var(--muted);margin-top:16px}.preview:hover span{color:var(--accent)}.meta{display:flex;justify-content:space-between;font:13px/1.6 monospace;color:var(--muted);margin-top:22px}h2{font-size:21px;font-weight:500;line-height:1.5;margin:10px 0 6px}article p{font-size:16px;color:var(--accent);margin:0}footer{margin-top:88px;padding:28px 0 40px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}@media(max-width:639px){header,main,footer{width:calc(100% - 40px)}.intro{padding:52px 0 36px}.intro p{font-size:15px}.total{font-size:52px;flex-shrink:0}.grid{grid-template-columns:1fr;gap:40px}.preview{padding:16px}h2{font-size:20px}}@media(prefers-reduced-motion:reduce){.preview img{transition:none;transform:none!important}}
</style></head><body><header><a href="/#about">← 返回个人简介</a><span>Le-soleile / 证书档案</span></header><main><section class="intro"><div><span class="eyebrow">SELECTED CERTIFICATES</span><h1>每一段投入，都有记录。</h1><p>收录现有的竞赛获奖证书。点击图片可查看原始图片或 PDF，原件保持原样。</p></div><div class="total">07<small>CERTIFICATES</small></div></section><section class="grid" aria-label="全部证书">'''+''.join(cards)+'''</section></main><footer>Le-soleile · 证书档案</footer></body></html>'''
(site/'certificates.html').write_text(html)
print('Built certificate archive:',len(items),'certificates')
